function topicKind(p,i){const kind=topicKinds[p.id]?.[i];if(!kind)throw new Error('Не задан тип tracking: '+p.id+':'+i);return kind}
function labelsForKey(key){let kind;const phase=/^(p\d+):m:(\d+)$/.exec(key),skill=/^skill:(.+):(\d+)$/.exec(key),aqa=/^aqa:(\d+)$/.exec(key);if(phase)kind=topicKinds[phase[1]]?.[Number(phase[2])];else if(skill)kind=skillKinds[skill[1]]?.[Number(skill[2])];else if(aqa)kind=aqaKinds[Number(aqa[1])];if(!['concept','action'].includes(kind))throw new Error('Нет шкалы для '+key);return kind==='action'?actionLabels:masteryLabels}
function topicReady(p,i){return Number(state.mastery[`${p.id}:m:${i}`]||0)>=3}
function renderTopics(p){const groups=[['setup','Настройка окружения'],['concept','Понимание и применение'],['action','Рабочие действия']];return groups.map(([kind,title])=>{const entries=p.topics.map((text,i)=>({text,i})).filter(({i})=>topicKind(p,i)===kind);if(!entries.length)return '';return `<div class="label-sm">${title}</div>`+entries.map(({text,i})=>{const key=`${p.id}:m:${i}`,value=Number(state.mastery[key]||0);if(kind==='setup'){const item=setupTopics[i];return `<div class="setup-item"><label class="practice-row"><input type="checkbox" data-setup="${key}" ${value>=3?'checked':''}><span>${esc(item.title)}</span></label><p class="muted">Проверка: ${esc(item.check)}</p>${value>0&&value<3?'<p class="muted">Прежняя частичная отметка сохранена. Подтверди настройку после проверки.</p>':''}</div>`}return `<div class="mastery-row"><span>${esc(text)}</span>${masterySelect(key,value,kind==='action'?actionLabels:masteryLabels)}</div>`}).join('')}).join('')}

